import{useEffect,useState}from"react";const menu=["Centro de Mando","Cobertura Curricular","Planificaciones IA","Evaluaciones IA","Cursos y Asignaturas","Currículum","Cobertura TP","Alertas y Mejora","Reportes","Administración"];const rows=[["1° Básico A",88,91,82,86],["2° Básico A",84,72,89,80],["4° Básico A",91,78,86,88],["8° Básico A",76,64,81,85],["2° Medio A",89,83,74,90]];function Cell({n}:{n:number}){return <td><span className={n>=80?"good":n>=70?"warn":"bad"}>{n}%</span></td>}function Shell({tab,setTab,children,user,onLogout}:{tab:string,setTab:(x:string)=>void,children:React.ReactNode,user:any,onLogout:()=>void}){const permissions:any={SUPERADMIN:menu,SOSTENEDOR:["Centro de Mando","Cobertura Curricular","Reportes","Administración"],DIRECTOR:["Centro de Mando","Cobertura Curricular","Planificaciones IA","Evaluaciones IA","Cursos y Asignaturas","Currículum","Cobertura TP","Alertas y Mejora","Reportes","Administración"],UTP:["Centro de Mando","Cobertura Curricular","Planificaciones IA","Evaluaciones IA","Cursos y Asignaturas","Currículum","Cobertura TP","Alertas y Mejora","Reportes"],DOCENTE:["Planificaciones IA","Evaluaciones IA","Cursos y Asignaturas","Currículum","Cobertura TP"]};const visible=permissions[user.role]||[];return <main><aside><div className="brand">Planificación<span>Docente</span></div><nav>{visible.map((x:string)=><button className={tab===x?"active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</nav><div className="role"><b>{user.name}</b><br/><span>{roleLabel(user.role)}</span><br/><small>Año académico 2027</small><button className="logout" onClick={onLogout}>Cerrar sesión</button></div></aside><section className="workspace">{children}</section></main>}const Field=({label,children}:{label:string,children:React.ReactNode})=><label><span>{label}</span>{children}</label>;const roleLabel=(r:string)=>({SUPERADMIN:"Superadministrador",SOSTENEDOR:"Sostenedor",DIRECTOR:"Director",UTP:"Jefe UTP",DOCENTE:"Docente"} as any)[r]||r;
function Login({onLogin}:{onLogin:(u:any)=>void}){const[email,setEmail]=useState("");const[password,setPassword]=useState("");const[error,setError]=useState("");const[loading,setLoading]=useState(false);const[needsSetup,setNeedsSetup]=useState(false);const[setup,setSetup]=useState({name:"",email:"",password:"",organization:""});useEffect(()=>{fetch("/api/setup").then(r=>r.json()).then(d=>setNeedsSetup(!!d.needsSetup)).catch(()=>{})},[]);const submit=async(e:any)=>{e.preventDefault();setLoading(true);setError("");const r=await fetch("/api/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,password})});const d=await r.json();setLoading(false);if(r.ok)onLogin(d.user);else setError(d.error||"No fue posible ingresar")};const activate=async(e:any)=>{e.preventDefault();setLoading(true);setError("");const r=await fetch("/api/setup",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(setup)});const d=await r.json();setLoading(false);if(r.ok){setNeedsSetup(false);setEmail(setup.email);setPassword(setup.password)}else setError(d.error||"No fue posible activar la plataforma")};return <div className="loginPage"><div className="loginCard"><div className="brand loginBrand">Planificación<span>Docente</span></div>{needsSetup?<><small>ACTIVACIÓN INICIAL</small><h1>Crear Superadministrador</h1><p>Esta configuración se habilita una sola vez.</p><form onSubmit={activate}><Field label="Nombre"><input required value={setup.name} onChange={e=>setSetup({...setup,name:e.target.value})}/></Field><Field label="Organización / Sostenedor"><input required value={setup.organization} onChange={e=>setSetup({...setup,organization:e.target.value})}/></Field><Field label="Correo"><input type="email" required value={setup.email} onChange={e=>setSetup({...setup,email:e.target.value})}/></Field><Field label="Contraseña"><input type="password" minLength={8} required value={setup.password} onChange={e=>setSetup({...setup,password:e.target.value})}/></Field>{error&&<div className="loginError">{error}</div>}<button className="primary" disabled={loading}>{loading?"Activando...":"Activar plataforma"}</button></form></>:<><small>GESTIÓN CURRICULAR CON IA</small><h1>Bienvenido</h1><p>Ingresa con tu cuenta institucional.</p><form onSubmit={submit}><Field label="Correo electrónico"><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="usuario@institucion.cl"/></Field><Field label="Contraseña"><input type="password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="Contraseña"/></Field>{error&&<div className="loginError">{error}</div>}<button className="primary" disabled={loading}>{loading?"Ingresando...":"Ingresar"}</button></form></>}<div className="loginFoot">Planificación · Evaluación · Cobertura · Evidencia</div></div></div>}
export default function Home(){const[user,setUser]=useState<any>(null);const[checking,setChecking]=useState(true);const[tab,setTab]=useState("Centro de Mando");const[generated,setGenerated]=useState(false);useEffect(()=>{fetch("/api/session").then(r=>r.json()).then(d=>{if(d.user){setUser(d.user);if(d.user.role==="DOCENTE")setTab("Planificaciones IA")}setChecking(false)}).catch(()=>setChecking(false))},[]);const logout=async()=>{await fetch("/api/session",{method:"DELETE"});setUser(null)};if(checking)return <div className="loginPage"><div className="loginCard"><b>Cargando Planificación Docente…</b></div></div>;if(!user)return <Login onLogin={(u)=>{setUser(u);setTab(u.role==="DOCENTE"?"Planificaciones IA":"Centro de Mando")}}/>;const title=tab==="Centro de Mando"?"Seguimiento curricular institucional":tab;return <Shell tab={tab} setTab={setTab} user={user} onLogout={logout}><header><div><small>{tab.toUpperCase()}</small><h1>{title}</h1><p>{tab==="Centro de Mando"?"Del currículum oficial a la evidencia de aprendizaje.":"Herramienta integrada al seguimiento curricular institucional."}</p></div><select><option>2027</option><option>2026</option></select></header>{tab==="Centro de Mando"?<RealDashboard/>:tab==="Planificaciones IA"?<Generator type="planificación" generated={generated} setGenerated={setGenerated}/>:tab==="Evaluaciones IA"?<Generator type="evaluación" generated={generated} setGenerated={setGenerated}/>:tab==="Cobertura TP"?<TPDashboard/>:tab==="Cursos y Asignaturas"?<AcademicPanel/>:tab==="Administración"?<AdminPanel/>:<article className="panel placeholder"><h2>{tab}</h2><p>Este módulo quedará conectado al Centro de Mando y a la trazabilidad por Objetivos de Aprendizaje.</p><button onClick={()=>setTab(tab==="Cobertura Curricular"?"Planificaciones IA":"Centro de Mando")}>Continuar →</button></article>}<footer><b>Planificado → Implementado → Evaluado → Nivel de logro</b><span>Planificación Docente · Gestión curricular basada en evidencia</span></footer></Shell>};function RealDashboard(){const[d,setD]=useState<any>(null);const[e,setE]=useState("");useEffect(()=>{fetch("/api/dashboard").then(async r=>{const x=await r.json();if(r.ok)setD(x);else setE(x.error||"No fue posible cargar")}).catch(()=>setE("No fue posible cargar"))},[]);if(e)return <article className="panel"><h2>Centro de Mando</h2><p>{e}</p></article>;if(!d)return <article className="panel"><h2>Centro de Mando</h2><p>Cargando datos curriculares reales…</p></article>;const k=d.kpis;return <><div className="cards">{[["OA PLANIFICADOS",k.planned,"Con trazabilidad"],["OA IMPLEMENTADOS",k.implemented,"Registrados como trabajados"],["OA EVALUADOS",k.evaluated,"Con evidencia evaluativa"],["LOGRO PROMEDIO",k.achievement==null?"—":k.achievement+"%","Resultados registrados"],["CURSOS",k.courses,"Año "+d.year]].map((x:any)=><article key={x[0]}><small>{x[0]}</small><strong>{x[1]}</strong><p>{x[2]}</p></article>)}</div><article className="panel matrix"><div className="panelHead"><div><small>TRAZABILIDAD REAL</small><h2>Planificado → Implementado → Evaluado</h2></div></div><table><thead><tr><th>Curso</th><th>OA planificados</th><th>OA implementados</th><th>OA evaluados</th><th>Implementación</th><th>Evaluación</th></tr></thead><tbody>{d.rows.map((r:any)=><tr key={r.id}><th>{r.course}</th><td>{r.plannedOA}</td><td>{r.implementedOA}</td><td>{r.evaluatedOA}</td><Cell n={r.implementationPct}/><Cell n={r.evaluationPct}/></tr>)}</tbody></table>{!d.rows.length&&<p className="muted">Aún no existen cursos con información curricular para este año.</p>}</article></>}
function Generator({type,generated,setGenerated}:{type:string,generated:boolean,setGenerated:(x:boolean)=>void}){const evaluation=type==="evaluación";if(evaluation)return <RealAssessmentGenerator/>;return <RealPlanningGenerator/>}
function RealAssessmentGenerator(){const[data,setData]=useState<any>({courses:[],objectives:[],aiReady:false});const[courseId,setCourseId]=useState("");const[subject,setSubject]=useState("");const[selected,setSelected]=useState<string[]>([]);const[type,setType]=useState("SUMMATIVE");const[instrument,setInstrument]=useState("Prueba mixta");const[generationMode,setGenerationMode]=useState<"AI"|"TEACHER">("AI");const[itemComposition,setItemComposition]=useState([{type:"Selección múltiple",count:10},{type:"Verdadero/Falso",count:5},{type:"Desarrollo",count:5}]);const[questions,setQuestions]=useState(20);const[totalScore,setTotalScore]=useState(40);const[difficulty,setDifficulty]=useState(60);const[itemScores,setItemScores]=useState<number[]>(Array(20).fill(2));const[duration,setDuration]=useState("60 minutos");const[instructions,setInstructions]=useState("");const[result,setResult]=useState<any>(null);const[editing,setEditing]=useState(false);const[editJson,setEditJson]=useState("");const[printMode,setPrintMode]=useState<"student"|"key">("student");const[msg,setMsg]=useState("");const[loading,setLoading]=useState(false);
const load=async()=>{const r=await fetch("/api/ai-assessment");const d=await r.json();if(r.ok){setData(d);if(!courseId&&d.courses?.[0]){setCourseId(d.courses[0].id);setSubject(d.courses[0].teachingAssignments?.[0]?.subject||"")}}else setMsg(d.error||"No fue posible cargar")};useEffect(()=>{load()},[]);
const course=data.courses?.find((x:any)=>x.id===courseId);const subs=Array.from(new Set((course?.teachingAssignments||[]).map((x:any)=>x.subject))) as string[];const objectives=(data.objectives||[]).filter((x:any)=>x.level===course?.level&&x.subject===subject);
const scoreSum=itemScores.slice(0,questions).reduce((a,v)=>a+(Number(v)||0),0);const passingScore=(totalScore*difficulty/100).toFixed(1);const changeQuestions=(n:number)=>{const q=Math.max(1,Math.min(60,n));setQuestions(q);setItemScores(old=>Array.from({length:q},(_,i)=>old[i]??1))};const changeCourse=(id:string)=>{setCourseId(id);const q=data.courses?.find((x:any)=>x.id===id);setSubject(q?.teachingAssignments?.[0]?.subject||"");setSelected([]);setResult(null)};
const generate=async()=>{if(!courseId||!subject||!selected.length){setMsg("Selecciona curso, asignatura y al menos un OA.");return}setLoading(true);setMsg("Generando evaluación con IA...");const r=await fetch("/api/ai-assessment",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({courseId,subject,objectiveIds:selected,type,instrument,generationMode,itemComposition,questions,totalScore,difficulty,itemScores,duration,instructions})});const d=await r.json();setLoading(false);if(r.ok){setResult(d.assessment);setEditJson(JSON.stringify(d.assessment.content,null,2));setMsg("✓ Evaluación generada y guardada")}else setMsg(d.detail?d.error+": "+d.detail:d.error||"No fue posible generar")};
const saveEdit=async()=>{try{const content=JSON.parse(editJson);const r=await fetch("/api/ai-assessment",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:result.id,title:content.titulo||result.title,content})});const d=await r.json();if(r.ok){setResult({...result,title:d.assessment.title,content:d.assessment.content});setEditing(false);setMsg("✓ Correcciones guardadas")}else setMsg(d.error||"No fue posible guardar")}catch{setMsg("El contenido editado no tiene un formato válido")}};
const print=(mode:"student"|"key")=>{setPrintMode(mode);setTimeout(()=>window.print(),100)};const p=result?.content;
return <div className="builder"><article className="panel form"><div className="step">1 · EVALUACIÓN ALINEADA AL CURRÍCULUM</div><h2>Crear evaluación con IA</h2>{msg&&<div className={msg.startsWith("✓")?"success":"muted"}>{msg}</div>}<div className="formgrid"><Field label="Curso"><select value={courseId} onChange={e=>changeCourse(e.target.value)}><option value="">Seleccionar curso</option>{data.courses?.map((x:any)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Asignatura"><select value={subject} onChange={e=>{setSubject(e.target.value);setSelected([])}}><option value="">Seleccionar asignatura</option>{subs.map(x=><option key={x}>{x}</option>)}</select></Field></div><Field label="Objetivos de Aprendizaje"><div className="oaList">{objectives.length?objectives.map((oa:any)=><div className="oa" key={oa.id}><b>{oa.code}</b><span>{oa.text}</span><input type="checkbox" checked={selected.includes(oa.id)} onChange={()=>setSelected(selected.includes(oa.id)?selected.filter(x=>x!==oa.id):[...selected,oa.id])}/></div>):<div className="oa"><span>No hay OA oficiales cargados para esta combinación.</span></div>}</div></Field><div className="formgrid"><Field label="Modalidad de generación"><select value={generationMode} onChange={e=>setGenerationMode(e.target.value as "AI"|"TEACHER")}><option value="AI">Automática con IA</option><option value="TEACHER">Configuración docente</option></select></Field><Field label="Tipo"><select value={type} onChange={e=>setType(e.target.value)}><option value="SUMMATIVE">Sumativa</option><option value="FORMATIVE">Formativa</option><option value="DIAGNOSTIC">Diagnóstica</option></select></Field><Field label="Instrumento"><select value={instrument} onChange={e=>setInstrument(e.target.value)}><option>Prueba mixta</option><option>Rúbrica</option><option>Pauta de observación</option><option>Lista de cotejo</option><option>Autoevaluación</option><option>Coevaluación</option><option>Ticket de salida</option></select></Field></div>{generationMode==="TEACHER"&&<div className="panel" style={{margin:"12px 0",padding:"14px"}}><b>Composición de ítems definida por el docente</b><p className="muted">Indica cuántos ítems de cada tipo deseas. La IA respetará esta estructura.</p>{itemComposition.map((row,i)=><div className="formgrid" key={i}><Field label={`Tipo ${i+1}`}><select value={row.type} onChange={e=>setItemComposition(old=>old.map((x,j)=>j===i?{...x,type:e.target.value}:x))}><option>Selección múltiple</option><option>Verdadero/Falso</option><option>Respuesta breve</option><option>Desarrollo</option><option>Resolución de problemas</option><option>Análisis de casos</option><option>Completación</option><option>Términos pareados</option></select></Field><Field label="Cantidad"><input type="number" min="0" max="60" value={row.count} onChange={e=>setItemComposition(old=>old.map((x,j)=>j===i?{...x,count:Math.max(0,Number(e.target.value)||0)}:x))}/></Field></div>)}<button onClick={()=>setItemComposition(old=>[...old,{type:"Respuesta breve",count:1}])}>+ Agregar tipo de ítem</button><p className="muted">Total configurado: {itemComposition.reduce((a,x)=>a+x.count,0)} ítems.</p></div>}<div className="formgrid"><Field label="Cantidad de ítems"><input type="number" min="1" max="60" value={questions} onChange={e=>changeQuestions(Number(e.target.value))}/></Field><Field label="Duración"><input value={duration} onChange={e=>setDuration(e.target.value)}/></Field></div>{type==="SUMMATIVE"&&<div className="panel" style={{margin:"12px 0",padding:"14px"}}><b>Configuración de puntaje y exigencia</b><div className="formgrid"><Field label="Puntaje total"><input type="number" min="1" value={totalScore} onChange={e=>setTotalScore(Math.max(1,Number(e.target.value)||1))}/></Field><Field label="Porcentaje de exigencia"><input type="number" min="1" max="100" value={difficulty} onChange={e=>setDifficulty(Math.max(1,Math.min(100,Number(e.target.value)||60)))}/></Field></div><small className="sourceTag">Puntaje de aprobación: {passingScore} pts. · Suma actual de ítems: {scoreSum} / {totalScore} pts.</small><div className="formgrid">{Array.from({length:questions},(_,i)=><Field key={i} label={`Ítem ${i+1}`}><input type="number" min="0" step="0.5" value={itemScores[i]??0} onChange={e=>setItemScores(old=>old.map((v,j)=>j===i?Math.max(0,Number(e.target.value)||0):v))}/></Field>)}</div>{scoreSum!==totalScore&&<div className="muted">La suma de puntajes por ítem debe ser igual al puntaje total.</div>}</div>}<Field label="Indicaciones para la IA"><textarea value={instructions} onChange={e=>setInstructions(e.target.value)}/></Field><button className="primary" disabled={loading||!data.aiReady||!selected.length||(type==="SUMMATIVE"&&scoreSum!==totalScore)||(generationMode==="TEACHER"&&itemComposition.reduce((a,x)=>a+x.count,0)!==questions)} onClick={generate}>{loading?"Generando...":"✦ Generar evaluación con IA"}</button></article><article className="panel preview"><div className="step">2 · INSTRUMENTO GENERADO</div>{!p?<div className="empty"><b>La evaluación aparecerá aquí</b><p>Quedará vinculada a sus OA y podrá corregirse antes de imprimir.</p></div>:<><div className="success noPrint">✓ Guardada · trazabilidad OA activa</div><div className="actions noPrint"><button onClick={()=>{setEditing(!editing);setEditJson(JSON.stringify(result.content,null,2))}}>{editing?"Cancelar edición":"Corregir evaluación"}</button><button onClick={()=>print("student")}>PDF estudiante</button><button onClick={()=>print("key")}>PDF pauta docente</button></div>{editing?<div className="noPrint"><Field label="Editor de la evaluación"><textarea style={{minHeight:"520px",fontFamily:"monospace"}} value={editJson} onChange={e=>setEditJson(e.target.value)}/></Field><button className="primary" onClick={saveEdit}>Guardar correcciones</button></div>:<div className="assessmentPrint"><div className={printMode==="student"?"studentPrint":"studentPrint screenOnly"}><h2>{result.title}</h2>{p.configuracionSumativa&&<p><b>Puntaje total:</b> {p.configuracionSumativa.puntajeTotal} pts. &nbsp; <b>Exigencia:</b> {p.configuracionSumativa.porcentajeExigencia}%</p>}<div className="printStudentData"><b>Nombre:</b> ____________________ &nbsp; <b>Curso:</b> {result.course?.name||course?.name} &nbsp; <b>Fecha:</b> ________</div><div className="doc"><p>{p.instrucciones}</p>{p.criterios?.length>0&&<><h3>Criterios del instrumento</h3>{p.criterios.map((x:any,i:number)=><p key={i}>{typeof x==="string"?x:JSON.stringify(x)}</p>)}</>}{p.escala?.length>0&&<><h3>Escala</h3><p>{p.escala.map((x:any)=>typeof x==="string"?x:JSON.stringify(x)).join(" · ")}</p></>}<h3>Ítems / indicadores</h3>{(p.items||[]).map((x:any)=><div key={x.numero}><p><b>{x.numero}. {x.enunciado}</b> ({x.puntaje} pts.)</p>{x.alternativas?.map((a:string,i:number)=><p key={i}>{String.fromCharCode(65+i)}) {a}</p>)}</div>)}</div></div><div className={printMode==="key"?"keyPrint":"keyPrint screenOnly"}><h2>Pauta de corrección · {result.title}</h2><div className="doc">{p.configuracionSumativa&&<p><b>Puntaje total:</b> {p.configuracionSumativa.puntajeTotal} · <b>Exigencia:</b> {p.configuracionSumativa.porcentajeExigencia}% · <b>Puntaje aprobación:</b> {p.configuracionSumativa.puntajeAprobacion}</p>}<h3>Tabla de especificaciones</h3>{(p.tablaEspecificaciones||[]).map((x:any,i:number)=><p key={i}><b>{x.oa}</b> · {x.habilidad} · ítems {x.items} · {x.puntaje} pts.</p>)}<h3>Respuestas y pauta</h3>{(p.items||[]).map((x:any)=><p key={x.numero}><b>{x.numero}.</b> {x.respuestaCorrecta||"Según pauta"} · {x.puntaje} pts. · {x.oa}</p>)}{(p.pautaCorreccion||[]).map((x:any,i:number)=><p key={i}>{typeof x==="string"?x:JSON.stringify(x)}</p>)}<h3>Niveles de logro</h3>{(p.nivelesLogro||[]).map((x:any,i:number)=><p key={i}><b>{x.nivel}</b> · {x.desde}–{x.hasta} · {x.descripcion}</p>)}</div></div></div>}</>}</article></div>}
function RealPlanningGenerator(){const[data,setData]=useState<any>({courses:[],objectives:[],plannings:[],aiReady:false});const[courseId,setCourseId]=useState("");const[subject,setSubject]=useState("");const[selected,setSelected]=useState<string[]>([]);const[duration,setDuration]=useState("90 minutos");const[modality,setModality]=useState("Clase a clase");const[instructions,setInstructions]=useState("");const[includeAdaptations,setIncludeAdaptations]=useState(false);const[adaptationContext,setAdaptationContext]=useState("");const[result,setResult]=useState<any>(null);const[msg,setMsg]=useState("");const[loading,setLoading]=useState(false);
 const load=async()=>{const r=await fetch("/api/ai-planning");const d=await r.json();if(r.ok){setData(d);if(!courseId&&d.courses?.[0]){setCourseId(d.courses[0].id);setSubject(d.courses[0].teachingAssignments?.[0]?.subject||"")}}else setMsg(d.error||"No fue posible cargar el generador")};useEffect(()=>{load()},[]);
 const course=data.courses?.find((x:any)=>x.id===courseId);const availableSubjects=Array.from(new Set((course?.teachingAssignments||[]).map((x:any)=>x.subject))) as string[];const objectives=(data.objectives||[]).filter((x:any)=>x.level===course?.level&&x.subject===subject);
 const changeCourse=(id:string)=>{setCourseId(id);const q=data.courses?.find((x:any)=>x.id===id);setSubject(q?.teachingAssignments?.[0]?.subject||"");setSelected([]);setResult(null)};
 const generate=async()=>{if(!courseId||!subject||!selected.length){setMsg("Selecciona curso, asignatura y al menos un OA.");return}setLoading(true);setMsg("Generando planificación con IA...");setResult(null);const r=await fetch("/api/ai-planning",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({courseId,subject,objectiveIds:selected,duration,modality,instructions,includeAdaptations,adaptationContext})});const d=await r.json();setLoading(false);if(r.ok){setResult(d.planning);setMsg("✓ Planificación generada y guardada en PostgreSQL");load()}else setMsg(d.detail?d.error+": "+d.detail:d.error||"No fue posible generar")};
 const p=result?.content;return <div className="builder"><article className="panel form"><div className="step">1 · CONFIGURACIÓN CURRICULAR REAL</div><h2>Crear planificación con IA</h2><p>La IA utiliza el curso, la asignación docente y los OA almacenados en la plataforma.</p>{msg&&<div className={msg.startsWith("✓")?"success":"muted"}>{msg}</div>}<div className="formgrid"><Field label="Curso"><select value={courseId} onChange={e=>changeCourse(e.target.value)}><option value="">Seleccionar curso</option>{data.courses?.map((x:any)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Asignatura"><select value={subject} onChange={e=>{setSubject(e.target.value);setSelected([])}}><option value="">Seleccionar asignatura</option>{availableSubjects.map(x=><option key={x}>{x}</option>)}</select></Field></div><Field label="Objetivos de Aprendizaje (OA)"><div className="oaList">{objectives.length?objectives.map((oa:any)=><div className="oa" key={oa.id}><b>{oa.code}</b><span>{oa.text}</span><input type="checkbox" checked={selected.includes(oa.id)} onChange={()=>setSelected(selected.includes(oa.id)?selected.filter(x=>x!==oa.id):[...selected,oa.id])}/></div>):<div className="oa"><span>No hay OA oficiales cargados para esta combinación. El piloto actual está habilitado para Matemática 8° Básico.</span></div>}</div>{objectives.length>0&&<small className="sourceTag">Fuente curricular almacenada: Currículum Nacional · MINEDUC</small>}</Field><div className="formgrid"><Field label="Duración"><select value={duration} onChange={e=>setDuration(e.target.value)}><option>45 minutos</option><option>90 minutos</option><option>135 minutos</option></select></Field><Field label="Modalidad"><select value={modality} onChange={e=>setModality(e.target.value)}><option>Clase a clase</option><option>Unidad</option><option>Mensual</option></select></Field></div><Field label="Indicaciones para la IA"><textarea value={instructions} onChange={e=>setInstructions(e.target.value)} placeholder="Ej.: incorporar trabajo colaborativo, DUA, recursos digitales y ticket de salida..."/></Field><div className="oa"><div><b>Adecuaciones curriculares (opcional)</b><span>Actívalas cuando la planificación requiera ajustes específicos, diferenciados del DUA general.</span></div><input type="checkbox" checked={includeAdaptations} onChange={e=>setIncludeAdaptations(e.target.checked)}/></div>{includeAdaptations&&<Field label="Necesidades y contexto para la adecuación"><textarea value={adaptationContext} onChange={e=>setAdaptationContext(e.target.value)} placeholder="Ej.: barreras de acceso, apoyos requeridos, ritmo de aprendizaje, formas alternativas de participación o evaluación. Evita ingresar diagnósticos o datos personales innecesarios."/></Field>}<button className="primary" disabled={loading||!data.aiReady||!selected.length} onClick={generate}>{loading?"Generando con IA...":"✦ Generar planificación con IA"}</button>{!data.aiReady&&<small className="sourceTag">OPENAI_API_KEY no disponible en el servidor.</small>}</article><article className="panel preview"><div className="step">2 · RESULTADO Y REGISTRO</div>{p?<><div className="success">✓ Guardada · vinculada a curso y OA</div><h2>{result.title}</h2><div className="doc"><b>Objetivo de clase</b><p>{p.objetivoClase}</p><h3>Indicadores</h3><p>{(p.indicadores||[]).join(" · ")}</p>{["inicio","desarrollo","cierre"].map(k=><div key={k}><h3>{k.charAt(0).toUpperCase()+k.slice(1)} · {p[k]?.minutos||""}</h3><p><b>Docente:</b> {p[k]?.actividadesDocente}</p><p><b>Estudiantes:</b> {p[k]?.actividadesEstudiantes}</p></div>)}<h3>Evaluación formativa</h3><p>{p.evaluacionFormativa}</p><h3>DUA</h3><p>{(p.dua||[]).join(" · ")}</p>{p.adecuacionesCurriculares&&<><h3>Adecuaciones curriculares</h3><p>{Array.isArray(p.adecuacionesCurriculares)?p.adecuacionesCurriculares.join(" · "):p.adecuacionesCurriculares}</p></>}<h3>Recursos y evidencia</h3><p>{(p.recursos||[]).join(" · ")} · {p.evidencia}</p></div></>:<div className="empty"><b>La planificación aparecerá aquí</b><p>Al generar, se guardará automáticamente como borrador y quedará vinculada a los OA seleccionados.</p></div>}</article></div>}
function TPDashboard(){const[selected,setSelected]=useState("Mecánica Industrial");const[action,setAction]=useState<null|{type:string,module:any}>(null);const mods=tpModules.filter(m=>m.specialty===selected);if(action)return <TPGenerator type={action.type} module={action.module} back={()=>setAction(null)}/>;return <><div className="tpHero"><div><small>FORMACIÓN DIFERENCIADA TÉCNICO-PROFESIONAL</small><h2>Gestión curricular TP</h2><p>Especialidad → Módulo → OA → Planificación → Evaluación → Cobertura.</p></div><div className="tpStat"><b>{tpSpecialties.length}</b><span>Especialidades oficiales</span></div></div><article className="panel tpSelector"><div><small>ESPECIALIDAD</small><select value={selected} onChange={e=>setSelected(e.target.value)}>{tpSpecialties.map(x=><option key={x}>{x}</option>)}</select></div><div><small>ESTADO CURRICULAR</small><b>{mods.length?mods.length+" módulos verificados":"Módulos oficiales pendientes de carga"}</b></div></article>{mods.length>0?<article className="panel tpBlock"><div className="panelHead"><div><small>MÓDULOS OFICIALES</small><h2>{selected}</h2></div><span className="verified">✓ Currículum Nacional</span></div><div className="moduleGrid">{mods.map(m=><div className="moduleCard" key={m.id}><div><b>{m.code}</b><span>{m.level}</span></div><h3>{m.name}</h3>{m.mention&&<p>{m.mention}</p>}<small>{m.oa.length?m.oa.join(" · "):"OA por completar desde programa oficial"}</small><div className="moduleActions"><button onClick={()=>setAction({type:"planificación",module:m})}>Crear planificación</button><button onClick={()=>setAction({type:"evaluación",module:m})}>Crear evaluación</button></div></div>)}</div></article>:<article className="panel emptyTp"><b>Especialidad incorporada al catálogo nacional</b><p>Sus módulos se habilitarán cuando finalice la carga y verificación del programa oficial MINEDUC.</p></article>}<article className="panel tpCatalog"><div className="panelHead"><div><small>CATÁLOGO NACIONAL</small><h2>35 especialidades · 15 sectores</h2></div></div>{tpSectors.map(sector=><div className="sectorRow" key={sector}><b>{sector}</b><span>{tpCatalog.filter(x=>x.sector===sector).map(x=>x.specialty).join(" · ")}</span></div>)}</article></>}

function AdminPanel(){const[view,setView]=useState("colegios");const[editingUser,setEditingUser]=useState<any>(null);const[editingSchool,setEditingSchool]=useState<any>(null);const[data,setData]=useState<any[]>([]);const[msg,setMsg]=useState("");const[school,setSchool]=useState({name:"",rbd:"",commune:"",region:"Antofagasta",organizationId:""});const[user,setUser]=useState({name:"",email:"",password:"",role:"DIRECTOR",organizationId:"",schoolId:""});const load=async()=>{try{const r=await fetch("/api/admin");if(r.ok){const d=await r.json();setData(d);if(d[0]){setSchool(s=>({...s,organizationId:s.organizationId||d[0].id}));setUser(u=>({...u,organizationId:u.organizationId||d[0].id}))}}}catch{}};useEffect(()=>{load()},[]);const patch=async(body:any)=>{setMsg("Actualizando...");const r=await fetch("/api/admin",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Actualizado correctamente":d.error||"Error al actualizar");if(r.ok)load()};const remove=async(body:any)=>{if(!confirm(body.kind==="course"?"¿Quitar este curso?":"¿Quitar esta asignación docente?"))return;setMsg("Actualizando...");const r=await fetch("/api/academic",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Actualizado correctamente":d.error||"Error");if(r.ok)load()};const update=async(body:any)=>{setMsg("Actualizando...");const r=await fetch("/api/academic",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Curso actualizado":d.error||"Error");if(r.ok)load()};const save=async(body:any)=>{setMsg("Guardando...");const r=await fetch("/api/admin",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Guardado correctamente":d.error||"Error al guardar");if(r.ok)load()};const schools=data.flatMap((o:any)=>o.schools||[]);const users=data.flatMap((o:any)=>o.users||[]);return <><div className="tpHero"><div><small>ADMINISTRACIÓN CENTRAL</small><h2>Organizaciones, colegios y usuarios</h2><p>Superadministrador → Sostenedor → Colegio → Usuarios.</p></div><div className="tpStat"><b>{schools.length}</b><span>Colegios registrados</span></div></div><div className="adminTabs"><button className={view==="colegios"?"active":""} onClick={()=>setView("colegios")}>Colegios</button><button className={view==="usuarios"?"active":""} onClick={()=>setView("usuarios")}>Usuarios</button><button className={view==="estructura"?"active":""} onClick={()=>setView("estructura")}>Estructura</button><button className={view==="roles"?"active":""} onClick={()=>setView("roles")}>Roles y permisos</button></div>{msg&&<div className="success">{msg}</div>}{view==="colegios"&&<div className="builder"><article className="panel form"><div className="step">NUEVO ESTABLECIMIENTO</div><h2>Crear colegio</h2>{data.length===0?<><p className="muted">Primero crea el sostenedor u organización.</p><Field label="Nombre del sostenedor"><input id="orgName" placeholder="Corporación, DAEM, SLEP..."/></Field><button className="primary" onClick={()=>{const el=document.getElementById("orgName") as HTMLInputElement;save({kind:"organization",name:el?.value})}}>Crear sostenedor</button></>:<><Field label="Nombre"><input value={school.name} onChange={e=>setSchool({...school,name:e.target.value})}/></Field><div className="formgrid"><Field label="RBD"><input value={school.rbd} onChange={e=>setSchool({...school,rbd:e.target.value})}/></Field><Field label="Comuna"><input value={school.commune} onChange={e=>setSchool({...school,commune:e.target.value})}/></Field></div><div className="formgrid"><Field label="Región"><select value={school.region} onChange={e=>setSchool({...school,region:e.target.value})}>{["Arica y Parinacota","Tarapacá","Antofagasta","Atacama","Coquimbo","Valparaíso","Metropolitana","O'Higgins","Maule","Ñuble","Biobío","La Araucanía","Los Ríos","Los Lagos","Aysén","Magallanes"].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Sostenedor"><select value={school.organizationId} onChange={e=>setSchool({...school,organizationId:e.target.value})}>{data.map((o:any)=><option value={o.id} key={o.id}>{o.name}</option>)}</select></Field></div><button className="primary" onClick={()=>save({kind:"school",...school})}>Crear establecimiento</button></>}</article><article className="panel preview"><div className="step">ESTABLECIMIENTOS</div><h2>Administración de colegios</h2>{editingSchool&&<div className="adminEdit"><Field label="Nombre"><input value={editingSchool.name} onChange={e=>setEditingSchool({...editingSchool,name:e.target.value})}/></Field><div className="formgrid"><Field label="RBD"><input value={editingSchool.rbd||""} onChange={e=>setEditingSchool({...editingSchool,rbd:e.target.value})}/></Field><Field label="Comuna"><input value={editingSchool.commune||""} onChange={e=>setEditingSchool({...editingSchool,commune:e.target.value})}/></Field></div><div className="actions"><button onClick={()=>setEditingSchool(null)}>Cancelar</button><button className="primary" onClick={async()=>{await patch({kind:"school",id:editingSchool.id,name:editingSchool.name,rbd:editingSchool.rbd,commune:editingSchool.commune,region:editingSchool.region});setEditingSchool(null)}}>Guardar cambios</button></div></div>}{schools.length?schools.map((s:any)=><div className="adminRow" key={s.id}><div><b>{s.name}</b><span>{s.rbd||"Sin RBD"} · {s.commune||"Sin comuna"} · {s.region||"Sin región"}</span></div><div><span className="verified">{s.active?"Activo":"Inactivo"}</span><button onClick={()=>setEditingSchool({...s})}>Editar</button><button onClick={()=>patch({kind:"school",id:s.id,active:!s.active})}>{s.active?"Desactivar":"Activar"}</button></div></div>):<p className="muted">Aún no existen establecimientos.</p>}</article></div>}{view==="usuarios"&&<div className="builder"><article className="panel form"><div className="step">NUEVO USUARIO</div><h2>Crear usuario</h2><Field label="Nombre"><input value={user.name} onChange={e=>setUser({...user,name:e.target.value})}/></Field><Field label="Correo electrónico"><input type="email" value={user.email} onChange={e=>setUser({...user,email:e.target.value})}/></Field><Field label="Contraseña inicial"><input type="password" minLength={12} value={user.password} onChange={e=>setUser({...user,password:e.target.value})} placeholder="Mínimo 12 caracteres"/></Field><div className="formgrid"><Field label="Rol"><select value={user.role} onChange={e=>setUser({...user,role:e.target.value})}><option value="SOSTENEDOR">Sostenedor</option><option value="DIRECTOR">Director</option><option value="UTP">Jefe UTP</option><option value="DOCENTE">Docente</option></select></Field><Field label="Establecimiento"><select value={user.schoolId} onChange={e=>setUser({...user,schoolId:e.target.value})}><option value="">Acceso sostenedor / general</option>{schools.map((s:any)=><option value={s.id} key={s.id}>{s.name}</option>)}</select></Field></div><Field label="Sostenedor"><select value={user.organizationId} onChange={e=>setUser({...user,organizationId:e.target.value})}>{data.map((o:any)=><option value={o.id} key={o.id}>{o.name}</option>)}</select></Field><button className="primary" disabled={!data.length} onClick={()=>save({kind:"user",...user})}>Crear usuario</button></article><article className="panel preview"><div className="step">USUARIOS REGISTRADOS</div><h2>Control de acceso</h2>{editingUser&&<div className="adminEdit"><Field label="Nombre"><input value={editingUser.name} onChange={e=>setEditingUser({...editingUser,name:e.target.value})}/></Field><Field label="Nueva contraseña (opcional)"><input type="password" minLength={12} value={editingUser.password} onChange={e=>setEditingUser({...editingUser,password:e.target.value})} placeholder="Mínimo 12 caracteres"/></Field><div className="actions"><button onClick={()=>setEditingUser(null)}>Cancelar</button><button className="primary" onClick={async()=>{await patch({kind:"user",id:editingUser.id,name:editingUser.name,...(editingUser.password?{password:editingUser.password}:{})});setEditingUser(null)}}>Guardar cambios</button></div></div>}{users.length?users.map((u:any)=><div className="adminRow" key={u.id}><div><b>{u.name}</b><span>{u.role} · {u.email}</span></div><div><span className="verified">{u.active?"Activo":"Inactivo"}</span>{u.role!=="SUPERADMIN"&&<><button onClick={()=>setEditingUser({id:u.id,name:u.name,password:""})}>Editar</button><button onClick={()=>patch({kind:"user",id:u.id,active:!u.active})}>{u.active?"Desactivar":"Activar"}</button></>}</div></div>):<p className="muted">Aún no existen usuarios.</p>}</article></div>}{view==="estructura"&&<article className="panel"><div className="panelHead"><div><small>ESTRUCTURA INSTITUCIONAL</small><h2>Sostenedores, establecimientos y usuarios</h2></div></div>{data.map((o:any)=><div className="orgTree" key={o.id}><h3>{o.name}</h3><p>{o.schools?.length||0} establecimientos · {o.users?.length||0} usuarios</p>{(o.schools||[]).map((s:any)=><div className="schoolTree" key={s.id}><b>{s.name}</b><span>{s.rbd?"RBD "+s.rbd:"Sin RBD"} · {s.commune||"Sin comuna"}</span><div>{(o.users||[]).filter((u:any)=>u.schoolId===s.id).map((u:any)=><small key={u.id}>{roleLabel(u.role)} · {u.name}</small>)}</div></div>)}</div>)}</article>}{view==="roles"&&<article className="panel"><div className="panelHead"><div><small>PERMISOS</small><h2>Acceso según perfil</h2></div></div><div className="roleGrid">{[["Superadministrador","Gestiona sostenedores, colegios y usuarios"],["Sostenedor","Administra sus establecimientos"],["Director","Centro de Mando y gestión institucional"],["Jefe UTP","Currículum, cobertura, planificación y evaluación"],["Docente","Planifica, evalúa y registra implementación"]].map(x=><div className="moduleCard" key={x[0]}><h3>{x[0]}</h3><p>{x[1]}</p></div>)}</div></article>}</>}

function TPGenerator({type,module,back}:{type:string,module:any,back:()=>void}){const[done,setDone]=useState(false);const evaluation=type==="evaluación";return <div className="builder"><article className="panel form"><button className="backBtn" onClick={back}>← Volver a Cobertura TP</button><div className="step">TP · CONFIGURACIÓN CURRICULAR</div><h2>Crear {type} TP con IA</h2><div className="tpContext"><b>{module.specialty}</b><span>{module.level}{module.mention?" · "+module.mention:""}</span><strong>{module.code} · {module.name}</strong></div><Field label="Objetivos de Aprendizaje"><div className="oaList">{module.oa.length?module.oa.map((oa:string)=><div className="oa" key={oa}><b>{oa}</b><span>Objetivo oficial asociado al módulo</span><input type="checkbox" defaultChecked/></div>):<div className="oa"><span>OA pendiente de completar desde el programa oficial MINEDUC.</span></div>}</div></Field>{evaluation?<div className="formgrid"><Field label="Tipo"><select><option>Formativa</option><option>Sumativa</option><option>Diagnóstica</option></select></Field><Field label="Instrumento"><select><option>Rúbrica de desempeño</option><option>Lista de cotejo</option><option>Prueba mixta</option></select></Field></div>:<div className="formgrid"><Field label="Duración"><select><option>2 horas pedagógicas</option><option>4 horas pedagógicas</option><option>Unidad completa</option></select></Field><Field label="Modalidad"><select><option>Taller práctico</option><option>Teórico-práctica</option><option>Dual / Alternancia</option></select></Field></div>}<Field label="Indicaciones para la IA"><textarea placeholder="Contexto, recursos del taller, seguridad, metodología o adecuaciones..."/></Field><button className="primary" disabled={!module.oa.length} onClick={()=>setDone(true)}>✦ Generar {type} TP con IA</button>{!module.oa.length&&<small className="sourceTag">La generación se habilitará cuando los OA oficiales del módulo estén cargados.</small>}</article><article className="panel preview"><div className="step">RESULTADO TP</div>{done?<><div className="success">✓ Borrador vinculado al módulo y OA</div><h2>{module.name}</h2><div className="doc"><b>{module.specialty} · {module.code}</b><p>{evaluation?"Instrumento alineado al desempeño técnico, OA del módulo, criterios de evaluación y seguridad.":"Planificación técnico-práctica alineada al módulo, OA, desempeño esperado, seguridad y evidencia de aprendizaje."}</p></div><div className="actions"><button>Editar</button><button>Guardar</button><button>Exportar</button></div></>:<div className="empty"><b>Tu {type} TP aparecerá aquí</b><p>Conservará la trazabilidad Especialidad → Módulo → OA → Evidencia.</p></div>}</article></div>}
function HCOfferingsPanel(){const[level,setLevel]=useState("3° Medio");const[data,setData]=useState<any>({offerings:[],courses:[],teachers:[]});const[msg,setMsg]=useState("");const[selected,setSelected]=useState(hcDifferentiatedCatalog[0]?.name||"");const[custom,setCustom]=useState("");const[pick,setPick]=useState<Record<string,{courseId:string,teacherId:string}>>({});const load=async()=>{const r=await fetch("/api/hc-offerings?year=2027&level="+encodeURIComponent(level));if(r.ok)setData(await r.json())};useEffect(()=>{load()},[level]);const add=async(body:any)=>{const r=await fetch("/api/hc-offerings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...body,year:2027,level})});const d=await r.json();setMsg(r.ok?"✓ Oferta curricular agregada":d.error||"No fue posible guardar");if(r.ok){setCustom("");load()}};const remove=async(id:string,kind="offering")=>{const r=await fetch("/api/hc-offerings",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify(kind==="assignment"?{kind,id}:{id})});if(r.ok)load()};const assign=async(offeringId:string)=>{const p=pick[offeringId]||{} as any;if(!p.courseId||!p.teacherId){setMsg("Selecciona curso y docente");return}const r=await fetch("/api/hc-offerings",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({kind:"assignment",offeringId,...p})});const d=await r.json();setMsg(r.ok?"✓ Docente asignado a la oferta HC":d.error||"No fue posible asignar");if(r.ok)load()};const official=hcDifferentiatedCatalog.find(x=>x.name===selected);return <article className="panel hcOfferings"><div className="panelHead"><div><small>FORMACIÓN DIFERENCIADA HC</small><h2>Oferta HC 3° y 4° Medio</h2><p>UTP define la oferta del establecimiento y la vincula con cursos y docentes.</p></div><select value={level} onChange={e=>setLevel(e.target.value)}><option>3° Medio</option><option>4° Medio</option></select></div>{msg&&<div className="success">{msg}</div>}<div className="builder"><div className="form"><Field label="Catálogo oficial MINEDUC"><select value={selected} onChange={e=>setSelected(e.target.value)}>{hcDifferentiatedCatalog.map(x=><option key={x.name}>{x.name}</option>)}</select></Field><p className="muted">{official?.area} · {official?.weeklyHours} horas semanales · MINEDUC</p><button className="primary" onClick={()=>official&&add({name:official.name,source:"MINEDUC"})}>Agregar a la oferta</button></div><div className="form"><Field label="Opción institucional"><input value={custom} onChange={e=>setCustom(e.target.value)} placeholder="Nombre de la opción institucional"/></Field><p className="muted">Se identificará como Institucional, separada del catálogo oficial.</p><button disabled={!custom.trim()} onClick={()=>add({name:custom,source:"INSTITUTIONAL"})}>Crear opción institucional</button></div></div><div className="hcOfferList">{data.offerings?.length?data.offerings.map((x:any)=>{const p=pick[x.id]||{courseId:"",teacherId:""};return <div className="hcOfferCard" key={x.id}><div className="adminRow"><div><b>{x.name}</b><span>{x.area||"Oferta propia"} · {x.weeklyHours?x.weeklyHours+" h/sem":"Horas por definir"}</span></div><div><span className="verified">{x.source==="MINEDUC"?"MINEDUC":"Institucional"}</span><button onClick={()=>remove(x.id)}>Quitar</button></div></div><div className="hcAssign"><select value={p.courseId} onChange={e=>setPick({...pick,[x.id]:{...p,courseId:e.target.value}})}><option value="">Seleccionar curso HC</option>{data.courses?.map((q:any)=><option key={q.id} value={q.id}>{q.name}</option>)}</select><select value={p.teacherId} onChange={e=>setPick({...pick,[x.id]:{...p,teacherId:e.target.value}})}><option value="">Seleccionar docente</option>{data.teachers?.map((t:any)=><option key={t.id} value={t.id}>{t.name}</option>)}</select><button onClick={()=>assign(x.id)}>Asignar</button></div>{x.teachingAssignments?.map((a:any)=><small className="assignmentLine" key={a.id}>{a.course.name} · {a.teacher.name} <button onClick={()=>remove(a.id,"assignment")}>Quitar</button></small>)}</div>}):<p className="muted">Aún no se ha configurado oferta para {level}.</p>}</div></article>}
function AcademicPanel(){
 const[data,setData]=useState<any>({courses:[],teachers:[]});const[msg,setMsg]=useState("");const[jec,setJec]=useState<boolean|null>(null);const[level,setLevel]=useState("1° Básico");const[track,setTrack]=useState("BASICA");const[selectedLetters,setSelectedLetters]=useState<string[]>(["A"]);const[assignment,setAssignment]=useState({courseId:"",subject:"Matemática",teacherId:""});
 const letters="ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");const levels=["Prekínder","Kínder","1° Básico","2° Básico","3° Básico","4° Básico","5° Básico","6° Básico","7° Básico","8° Básico","1° Medio","2° Medio","3° Medio","4° Medio"];
 const inferTrack=(x:string)=>x==="Prekínder"||x==="Kínder"?"PARVULARIA":x.includes("Básico")?"BASICA":"HC";
 const load=async()=>{const r=await fetch("/api/academic?year=2027");if(r.ok){const d=await r.json();setData(d);setJec(d.academicYear?.jec??null);if(d.courses?.[0])setAssignment((x:any)=>({...x,courseId:x.courseId||d.courses[0].id}));if(d.teachers?.[0])setAssignment((x:any)=>({...x,teacherId:x.teacherId||d.teachers[0].id}))}};
 useEffect(()=>{load()},[]);
 const remove=async(body:any)=>{if(!confirm(body.kind==="course"?"¿Quitar este curso?":"¿Quitar esta asignación docente?"))return;setMsg("Actualizando...");const r=await fetch("/api/academic",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Actualizado correctamente":d.error||"Error");if(r.ok)load()};const update=async(body:any)=>{setMsg("Actualizando...");const r=await fetch("/api/academic",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Curso actualizado":d.error||"Error");if(r.ok)load()};const save=async(body:any)=>{setMsg("Guardando...");const r=await fetch("/api/academic",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...body,year:2027})});const d=await r.json();setMsg(r.ok?"✓ Guardado correctamente":d.error||"Error");if(r.ok)load();return r.ok};
 const createCourses=async()=>{if(!selectedLetters.length){setMsg("Selecciona al menos un paralelo");return}setMsg("Creando cursos...");let ok=0;for(const letter of selectedLetters){if(await save({kind:"course",name:`${level} ${letter}`,level,track}))ok++}setMsg(`✓ ${ok} curso(s) procesados para ${level}`)};
 const changeLevel=(v:string)=>{setLevel(v);setTrack(inferTrack(v))};
 const saveJec=async(v:boolean)=>{setJec(v);const r=await fetch("/api/academic",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({year:2027,jec:v})});setMsg(r.ok?"✓ Régimen de jornada guardado":"No fue posible guardar el régimen")};
 return <><div className="tpHero"><div><small>CONFIGURACIÓN ACADÉMICA</small><h2>Cursos y Asignaturas</h2><p>El Director define los niveles y paralelos que existen realmente en su establecimiento.</p></div><div className="tpStat"><b>{data.courses?.length||0}</b><span>Cursos 2027</span></div></div>{msg&&<div className="success">{msg}</div>}<article className="panel jecPanel"><div><small>RÉGIMEN DE JORNADA</small><h2>Plan de estudios del establecimiento</h2><p>Seleccione la modalidad que corresponde al establecimiento para este año académico.</p></div><div className="jecChoices"><button className={jec===true?"active":""} onClick={()=>saveJec(true)}>Con JEC</button><button className={jec===false?"active":""} onClick={()=>saveJec(false)}>Sin JEC</button></div></article><div className="builder"><article className="panel form"><div className="step">CONFIGURAR CURSOS</div><h2>Nivel y paralelos A–Z</h2><Field label="Nivel"><select value={level} onChange={e=>changeLevel(e.target.value)}>{levels.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Modalidad"><select value={track} onChange={e=>setTrack(e.target.value)}><option value="PARVULARIA">Parvularia</option><option value="BASICA">Básica</option><option value="HC">Media HC</option><option value="TP">Media TP</option></select></Field><Field label="Paralelos que existen en el establecimiento"><div className="letterGrid">{letters.map(letter=><button type="button" key={letter} className={selectedLetters.includes(letter)?"active":""} onClick={()=>setSelectedLetters(selectedLetters.includes(letter)?selectedLetters.filter(x=>x!==letter):[...selectedLetters,letter].sort())}>{letter}</button>)}</div></Field><p className="muted">Se crearán: {selectedLetters.length?selectedLetters.map(x=>level+" "+x).join(" · "):"ningún curso seleccionado"}</p><button className="primary" onClick={createCourses}>Crear cursos seleccionados</button></article><article className="panel form"><div className="step">ASIGNACIÓN DOCENTE</div><h2>Asignar asignatura</h2><Field label="Curso"><select value={assignment.courseId} onChange={e=>setAssignment({...assignment,courseId:e.target.value})}>{data.courses?.map((x:any)=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field><Field label="Asignatura"><select value={assignment.subject} onChange={e=>setAssignment({...assignment,subject:e.target.value})}>{(curricularSubjects(data.courses?.find((x:any)=>x.id===assignment.courseId)?.level)||[]).map(x=><option key={x}>{x}</option>)}<option value="__custom">+ Agregar asignatura institucional</option></select></Field>{assignment.subject==="__custom"&&<Field label="Asignatura institucional"><input placeholder="Nombre de la asignatura" onChange={e=>setAssignment({...assignment,subject:e.target.value})}/></Field>}<Field label="Docente"><select value={assignment.teacherId} onChange={e=>setAssignment({...assignment,teacherId:e.target.value})}>{data.teachers?.map((x:any)=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field><button className="primary" disabled={!data.courses?.length||!data.teachers?.length} onClick={()=>save({kind:"assignment",...assignment})}>Asignar docente</button></article></div><article className="panel"><div className="panelHead"><div><small>ESTRUCTURA 2027</small><h2>Cursos configurados por el establecimiento</h2></div></div>{data.courses?.length?data.courses.map((x:any)=><div className="adminRow" key={x.id}><div><b>{x.name}</b><span>{x.level} · {x.track}</span>{x.teachingAssignments?.map((a:any)=><small className="assignmentLine" key={a.id}>{a.subject} · {a.teacher.name} <button onClick={()=>remove({kind:"assignment",id:a.id})}>Quitar</button></small>)}</div><div className="courseActions"><select value={x.track} onChange={e=>update({kind:"course",id:x.id,track:e.target.value})}><option value="PARVULARIA">Parvularia</option><option value="BASICA">Básica</option><option value="HC">Media HC</option><option value="TP">Media TP</option></select><span className="verified">{x.teachingAssignments?.length||0} asignaciones</span><button onClick={()=>remove({kind:"course",id:x.id})}>Quitar curso</button></div></div>):<p className="muted">El Director aún no ha configurado los cursos de este establecimiento.</p>}</article><HCOfferingsPanel/></>
}
